spec.msl_sketch:
The full, compilable-in-shape sketch is in scratchpad/trail/new/ufo/ufo_sketch.metal. It reuses EffectU, GOut, KIND_PARTICLE, fx_hash, fx_unit and fx_in_hole as they are. It has not been compiled: this box's xcrun has no metal. The core:

```metal
// k[0] hover  k[1] size  k[2] beam alpha  k[3] wake alpha  k[4] light turns/s  k[5] arc  k[6] tilt  k[7] depart
struct UfoPose { float2 c; float cs, sn, s, vis, cr, sr, side, gap, gx, beam, ext; };
static inline float ufo_cov(float d) { return clamp(0.5 - d, 0.0, 1.0); }
static inline float ufo_omega(constant EffectU& f) { return 4.0 / clamp(0.12 + 0.006 * f.len / f.unit, 0.16, 0.32); }
static inline UfoPose ufo_pose(constant EffectU& f, float a) {
    float c = f.unit;
    float2 cq = (f.c[0] + f.c[1] + f.c[2] + f.c[3]) * 0.25;
    float w = ufo_omega(f);
    float sig = 1.0 - (1.0 + w * a) * exp(-w * a);
    float2 on = f.tail + (cq - f.tail) * sig;
    float2 g = (f.hole.xy + f.hole.zw) * 0.5 - on;  float gap = length(g);
    float side = f.hole.y >= 1.35 * c ? 1.0 : -1.0;
    float2 pth = cq - f.tail; float pl = length(pth);
    float2 n = pl > 1e-3 ? float2(-pth.y, pth.x) / pl : float2(0.0, -side);
    if (n.y * side > 0.0) n = -n;
    float arc = min(f.k[5] * c, 0.12 * f.len) * 4.0 * sig * (1.0 - sig);
    float hov = 1.0 - smoothstep(0.1 * c, 0.6 * c, gap);
    float h1 = fx_unit(fx_hash(f.seed ^ 0x5bd1e995u)), h2 = fx_unit(fx_hash(f.seed));
    float bob = 0.035 * c * sinpi(2.0 * fract(2.2 * a + h1) - 1.0) * hov;
    float tl = max(a - f.k[7], 0.0), kk = clamp(tl / 0.18, 0.0, 1.0);
    UfoPose P;
    P.c = on + n * arc + float2(0.0, -side * f.k[0] * c + bob - side * 46.0 * c * tl * tl);
    float th = f.k[6] * clamp(g.x / (3.0 * c), -1.0, 1.0) + 0.05 * sinpi(2.0 * fract(1.3 * a + h2) - 1.0) * hov;
    P.cs = cos(th); P.sn = sin(th);                       // |th| <= 0.37: fast-math domain
    float grow = smoothstep(0.0, 0.08, a);
    P.vis = grow * (1.0 - smoothstep(0.0, 1.0, kk));
    P.s = f.k[1] * mix(0.5, 1.0, grow) * (1.0 - 0.6 * kk * kk);
    float rho = 2.0 * fract(f.k[4] * a + h2) - 1.0; P.cr = cospi(rho); P.sr = sinpi(rho);
    P.side = side; P.gap = gap; P.gx = g.x;
    P.ext = smoothstep(0.15, 0.25, a) * (1.0 - smoothstep(0.46, 0.54, a));
    P.beam = P.ext * (1.0 - smoothstep(0.15 * c, 0.6 * c, gap));
    return P;
}
static inline float ufo_vesica(float2 q) {            // r=1.331818 d=1.221818 b=0.53, tips on x
    float2 p = abs(q.yx);
    if ((p.y - 0.53) * 1.221818 > p.x * 0.53) return length(p - float2(0.0, 0.53));
    return length(p + float2(1.221818, 0.0)) - 1.331818;
}
static inline float ufo_dome(float2 p) {               // iq cut disk, r=0.22, h=0, y up
    const float r = 0.22; p.x = abs(p.x);
    float s = max(-r * p.x * p.x + r * r * (r - 2.0 * p.y), -r * p.y);
    return s < 0.0 ? length(p) - r : (p.x < r ? -p.y : length(p - float2(r, 0.0)));
}
static inline float ufo_smin(float a, float b, float k) { k *= 4.0; float h = max(k - abs(a - b), 0.0) / k; return min(a, b) - h * h * k * 0.25; }
constant float2 UFO_LIGHTS[5] = { float2(1,0), float2(0.309017,0.951057), float2(-0.809017,0.587785), float2(-0.809017,-0.587785), float2(0.309017,-0.951057) };
static inline float ufo_body(float2 p, UfoPose P, float c) {
    float u = P.s * c; float2 d = p - P.c;
    if (dot(d, d) > (0.62 * u + 1.0) * (0.62 * u + 1.0)) return 0.0;
    float2 q = float2(P.cs * d.x + P.sn * d.y, -P.sn * d.x + P.cs * d.y) / u;
    float dh = ufo_vesica(q) - 0.02;
    float sil = ufo_smin(dh, ufo_dome(float2(q.x, -0.04 - q.y)), 0.03);
    float light = 0.0;
    if (abs(q.y - 0.03) < 0.09) for (uint i = 0u; i < 5u; i++) {
        float cphi = P.cr * UFO_LIGHTS[i].x - P.sr * UFO_LIGHTS[i].y;
        float sphi = P.sr * UFO_LIGHTS[i].x + P.cr * UFO_LIGHTS[i].y;
        light = max(light, smoothstep(0.0, 0.35, cphi) * ufo_cov((length(q - float2(0.40 * sphi, 0.03)) - 0.045) * u));
    }
    return (0.50 * ufo_cov(sil * u) + ufo_cov(dh * u) * (0.30 + 0.20 * light)) * P.vis;
}
static inline float ufo_beam(float2 p, UfoPose P, constant EffectU& f) {
    if (P.beam <= 0.0) return 0.0;
    float c = f.unit;
    float2 top = P.c + float2(0.0, P.side * 0.117 * c * P.s);
    float2 ax = float2((f.hole.x + f.hole.z) * 0.5, P.side > 0.0 ? f.hole.y : f.hole.w) - top;
    float ln = length(ax); if (ln < 1.0) return 0.0;
    float2 nn = ax / ln, d = p - top;
    float along = dot(d, nn), across = abs(d.x * nn.y - d.y * nn.x), ff = clamp(along / ln, 0.0, 1.0);
    float hw = mix(0.14 * c * P.s, max(0.5 * (f.hole.z - f.hole.x) + 0.08 * c, 0.22 * c), ff);
    float edge = clamp(hw - across + 0.5, 0.0, 1.0) * clamp(ln * P.ext - along + 0.5, 0.0, 1.0) * clamp(along + 0.5, 0.0, 1.0);
    if (edge <= 0.0) return 0.0;
    float core = 1.0 - smoothstep(0.0, 0.6, across / max(hw, 1.0));
    float fr = fract(along / (0.22 * c) - fract(5.0 * f.age));
    return f.k[2] * P.vis * P.beam * edge * (0.55 + 0.45 * core) * (0.6 + 0.4 * ff) * (1.0 - 0.88 * fr * (1.0 - fr));
}
static inline float ufo_wake(float2 p, UfoPose P, constant EffectU& f) {
    float c = f.unit; if (f.age <= 0.0) return 0.0;
    UfoPose Q = ufo_pose(f, max(f.age - 0.06, 0.0));
    float2 v = P.c - Q.c; float l = length(v); if (l < 0.1 * c) return 0.0;
    float2 a = P.c - v / l * (0.2475 * c * P.s), ba = Q.c - a, pa = p - a;
    float h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-6), 0.0, 1.0);
    float dd = length(pa - ba * h) - mix(0.055 * c, 0.012 * c, h);
    return f.k[3] * P.vis * ufo_cov(dd) * (1.0 - h) * smoothstep(0.1 * c, 0.6 * c, l);
}
fragment float4 ufo_fragment(GOut in [[stage_in]], constant EffectU& f [[buffer(0)]]) {
    if (in.kind == KIND_PARTICLE) {                    // exhaust ring
        float a = in.color.a * (1.0 - smoothstep(0.0, 0.22, abs(length(in.uv) - 0.72)));
        return float4(in.color.rgb * a, a);
    }
    float2 p = in.pos.xy - f.origin;
    if (fx_in_hole(p, f) || f.age >= f.life) return float4(0.0);
    UfoPose P = ufo_pose(f, f.age);
    float a = ufo_wake(p, P, f);
    float b = ufo_beam(p, P, f); a = b + a * (1.0 - b);
    float s = ufo_body(p, P, f.unit); a = s + a * (1.0 - s);
    a *= in.color.a;
    return float4(in.color.rgb * a, a);
}
```

spec.rust_reference_notes:
**What cells.rs must port** (a third spelling, as fire_reference is), in f32. proto3.py in the scratchpad is written in exactly that shape and is the seed.

**(a) ufo_pose(f, age):**
- the centroid of the 4 prefix corners;
- omega = 4/clamp(0.12 + 0.006*len/unit, 0.16, 0.32);
- sigma = 1 - (1 + w a)*exp(-w a);
- the side rule `hole.top >= 1.35*unit`;
- the normal sign flip, arc, bob, tilt and leave;
- sinpi(x) = (x*PI).sin() and cospi likewise, always on 2*fract(.) - 1;
- fract(x) = x - x.floor();
- theta's cos and sin with |theta| <= 0.37;
- h1 = unit(hash(seed ^ 0x5bd1e995)) and h2 = unit(hash(seed)), with the Word hash already in cells.rs.

**(b) Distance functions, with the literals exactly as in the shader:**
- vesica: r = 1.331818, d = 1.221818, b = 0.53, axes swapped;
- dome: cut disk with h = 0;
- quadratic smin with k = 0.03;
- the five light constants, written as the same 6-digit literals in both, never computed on one side and typed on the other.

**(c) The parts and the composite:** beam, wake (a second pose at age - 0.06, with the same corners) and body, composited in the order wake, beam, body with a = x + a(1 - x), then premultiplied by the record colour.

**(d) The ring particle:** a = color.a*(1 - smoothstep(0, 0.22, |len(uv) - 0.72|)) over the record's uv, as fire_frame does for embers.

**Precision:**
- Every transcendental is inside MSL Table 8.2's fast-math domain.
- exp's argument is at most -w*a >= -25*0.72 = -18, which is 3 + 36 ulp, relatively 4e-6.
- sqrt is x*rsqrt(x). Division is 2.5 ulp.
- Expect the fire's tolerance: one step of 255, and a handful of pixels a scene. This is unmeasured until the oracle runs.
- No precise:: math should be needed. If the rotation or the ring's fract shows more than 20 pixels a step off at the fract wrap, switch just those to precise::.

**The region hook's Rust side (ufo::pose, ufo::region)** must spell the pose identically to the shader. The first gate the implementation needs is `every_lit_pixel_is_in_a_band`, the counterpart of `every_pixel_within_reach_is_in_a_band`: scan the whole frame with the reference, and require every pixel with alpha > 0 to lie in some Band record. The prototype's audit asserted 0 outside over 32 frames.

**Other tests to name:**
1. `ufo::PARAMS` layout at 24-31 (hover, size, beam, wake, light_hz, arc, tilt, depart), plus life = 0.72 and reach = 0.1 in the prefix.
2. The records are the fill at 0xFF (bands) and at the glow (particles). The oracle cannot catch wrong record colours.
3. The flight passes through the tail at age 0 and is within 4% of Cq at 1.3T. The beam is 0 whenever |gap| > 0.6c. The side flips at hole.top = 1.35c.
4. Puffs: count clamp(round(2*len/unit), 4, 20), each dead by end(), the seed decides them, and none are alive after 0.63 s.
5. A retarget arm in the oracle: a Segment retargeted at 0.2 s, where the saucer must be continuous (pose delta over 1 ms under 2 px) and the beam must open over the new cursor.
6. Fire stays byte-identical under the region hook: dump the eight fire frames before and after, as f202aea did.
7. The oracle scenes: across, down, top row (beam up) and retarget, each at four ages. Both arms must match the reference, and nothing may change outside the records.
8. Every scene must put a pixel inside the beam and one on a rim light, so neither part can pass vacuously.

No new Kind: the kind pins are unchanged. every_effect_has_its_fragment_in_the_library covers "ufo_fragment" once Effect::ALL includes Ufo.
